        return "ui"
    if any(x in p for x in ("config", ".yaml", ".yml", "next.config", "vite.config", "package.json")):
        return "config"
    vf = {str(x).lower() for x in (repo_v2.get("validation_files") or []) if x}
    sf = {str(x).lower() for x in (repo_v2.get("db_schema_files") or []) if x}
