    ]
    for pat in patterns:
        for m in re.finditer(pat, text, re.IGNORECASE):
            p = m.group(1).replace("\\", "/")
            while "//" in p:
                p = p.replace("//", "/")
            low = p.lower()
            if "node_modules" in low or p in out:
                continue
            out.append(p)
            if len(out) >= limit:
