def _language_for_suffix(suffix: str) -> str:
    s = suffix.lower()
    if s in (".ts", ".tsx"):
        return "typescript"
    if s in (".js", ".jsx"):
        return "javascript"
    if s == ".py":
        return "python"
    if s == ".json":
        return "json"
    if s == ".md":
        return "markdown"
    if s == ".sql":
        return "sql"
    return "unknown"


def _sha256_text(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8", errors="replace")).hexdigest()


def _sha256_bytes(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


