                files_changed.append(line[3:].strip())

        # 2. Diff Summary
        diff_output = subprocess.check_output(
            ["git", "diff", "--stat", "HEAD"],
            cwd=worker.worktree_path,
            text=True
        )
        diff_summary = diff_output if diff_output.strip() else "No changes detected."

        return files_changed, diff_summary
