            "",
            label,
            f"model call ({label}) took {max_model.duration_ms:.0f}ms",
        )
    )

shell_denied = sum(
    1
    for a in trace.approvals
    if not a.approved and "shell" in (a.approval_type or "").lower()
)
if shell_denied >= 2 and total_appr > 0:
    candidates.append(
