def normalize_task_status(status: str) -> str:
    """Map legacy task JSON status to SessionPhase string."""
    if not status:
        return SessionPhase.IDLE.value
    u = status.strip()
    if u in {p.value for p in SessionPhase}:
        return u
    return _LEGACY_TASK_STATUS_MAP.get(u.lower(), u)


