class TestStagnationDetector(unittest.TestCase):
    def test_reset_clears_stagnation_for_new_task(self) -> None:
        d = StagnationDetector(max_same_action_same_target=3)
        for _ in range(3):
            d.add_action("edit_file", "app/x.ts")
