) -> VerificationPlan:
    """
    Returns ordered verification checks. For TS/API edits: typecheck first, then build.
    If repair: rerun failed checks first. If low budget: single targeted check.
    """
    scope = _effective_scope_for_plan(scope, repo_v2)
    files = files_changed or []
    file_paths = [f.get("file", "") for f in files if f.get("file")]
    ts_exts = (".ts", ".tsx", ".js", ".jsx")
    is_ts_project = any(p.endswith(ts_exts) for p in file_paths) if file_paths else True
    if repo_v2 and isinstance(repo_v2, dict):
        langs = (repo_v2.get("stack") or {}).get("language") or []
        if isinstance(langs, list) and any("typescript" in str(x).lower() for x in langs):
            is_ts_project = True
    budget = budget_remaining if budget_remaining is not None else 100

    # Repair: rerun failed checks first, skip broader checks until fixed
    if failed_check_names:
        return VerificationPlan(
            check_names=failed_check_names,
            justification="Repair verification: rerunning failed check(s) first.",
        )

    if task_type == "docs_change":
        return VerificationPlan(check_names=[], justification="Documentation only; no verification.")
    if task_type == "type_fix":
        if budget < BUDGET_LOW_THRESHOLD:
            return VerificationPlan(check_names=["TypeCheck"], justification="Low budget: typecheck only.")
        return VerificationPlan(
            check_names=["TypeCheck", "Build"],
            justification="Type fix: typecheck first, then build.",

        )
    if task_type == "build_fix":
        return VerificationPlan(
            check_names=["Build", "TypeCheck", "Lint"],
            justification="Build fix requires full verification.",
        )

    # TS/API/data-layer: typecheck first (cheapest, high signal)
    if scope in ("api", "data") or (scope == "unknown" and is_ts_project):
        if budget < BUDGET_LOW_THRESHOLD:
            return VerificationPlan(
                check_names=["TypeCheck"],
                justification="Low budget: typecheck only to confirm compile.",
            )
        return VerificationPlan(
            check_names=["TypeCheck", "Build", "Lint"],
            justification="API/data layer: typecheck first, then build, lint.",
        )

    # Default: full suite (original order)
    if budget < BUDGET_LOW_THRESHOLD:
        return VerificationPlan(
            check_names=["TypeCheck"],
            justification="Low budget: typecheck only.",
        )
    return VerificationPlan(
        check_names=["Build", "TypeCheck", "Lint"],
        justification="Full verification.",
