def append_tool_trace(self, name: str, target: str, auto_approved: bool = False) -> None:
    """Queue one tool row; call flush_tool_segment after the batch executes."""
    tgt = (target or "").strip() or "—"
    if len(tgt) > 500:
        tgt = tgt[:497] + "…"
    mark = "✓ " if auto_approved else ""
    self._tool_segment_rows.append((str(name or "tool"), mark + escape(tgt)))

def flush_tool_segment(self) -> None:
    """Render queued tools: compact (una línea) por defecto, o panel si GHOST_TOOL_UI=panel."""
    if not self._tool_segment_rows:
        return
    if ghost_theme.ghost_tool_ui_mode() == "compact":
        chunks: List[str] = []
        for name, tgt in self._tool_segment_rows:
            chunks.append(f"[cyan]{escape(str(name))}[/cyan] [dim]·[/dim] {tgt}")
        line = " [dim]⚙[/dim] " + " [dim]│[/dim] ".join(chunks)
        try:
            w = int(self.console.width or 120)
        except (TypeError, ValueError):
            w = 120
        tm = Text.from_markup(line)
        max_plain = max(48, w - 2)
        if len(tm.plain) > max_plain:
            self.console.print(Text(tm.plain[: max(32, w - 8)] + "…", style="dim"))
        else:
            self.console.print(tm)
        self._tool_segment_rows = []
        return

    table = Table(
