def is_model_allowed(model_name: str) -> bool:
    if model_name in COMPAT_MODEL_ALIASES:
        return True
    if not MODEL_MAPPING:
        return False
    if model_name in MODEL_MAPPING or model_name in MODEL_MAPPING.values():
        return True
    resolved = resolve_upstream_model_id(model_name, MODEL_MAPPING)
    return resolved in MODEL_MAPPING.values()


def model_not_allowed_payload(model_name: str) -> Dict[str, Any]:
    """Structured 403 body: which id was rejected, registry health, and fix hints."""
    sample = sorted(MODEL_MAPPING.keys())[:16]
    payload: Dict[str, Any] = {
        "error": "model_not_allowed",
        "model": model_name,
        "model_registry_healthy": MODEL_REGISTRY_ERROR is None,
        "enabled_aliases_sample": sample,
        "compatibility_aliases": sorted(COMPAT_MODEL_ALIASES),
    }
    if MODEL_REGISTRY_ERROR:
        payload["registry_load_error"] = MODEL_REGISTRY_ERROR
        payload["hint"] = (
            "configs/models.yaml failed validation or could not be read — fix the file and restart. "
            "Until the registry loads, enabled model IDs are unavailable (403 on real models)."
        )
    else:
        payload["hint"] = (
            "Request an enabled registry name, its upstream_id from configs/models.yaml, "
            "or a compatibility alias (e.g. claude-sonnet-4-6 → kimi bridge)."
        )
    return payload

async def list_models():
    """OpenAI-style list aligned with configs/models.yaml (plus compatibility aliases)."""
    rows: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for name, m in ENABLED_MODELS.items():  # always iterable — ENABLED_MODELS is never undefined
        if name not in seen:
            seen.add(name)
            rows.append(
                {
                    "id": name,
                    "object": "model",
                    "created": 0,
                    "owned_by": "ghostllm",
                }
            )
        uid = getattr(m, "upstream_id", None) or ""
        if uid and uid not in seen:
            seen.add(uid)
            rows.append(
                {
                    "id": uid,
                    "object": "model",
                    "created": 0,
                    "owned_by": "nvidia",
                }
            )
    for alias in ("sonnet", "claude-3-5-sonnet-20241022", "claude-sonnet-4-6", "kimi"):
        if alias not in seen:
            seen.add(alias)
            rows.append(
                {
                    "id": alias,
                    "object": "model",
                    "created": 0,
                    "owned_by": "compatibility",
                }

