import json
import uuid
import logging
from typing import AsyncGenerator, Dict, Any, List, Optional

logger = logging.getLogger("ghostllm.adapters.stream")

class StreamNormalizer:
    """
    Stateful SSE normalizer for Anthropic protocol.
    Ensures message_start, content_block_start, and message_stop events 
    are precisely sequenced to satisfy Claude Code's internal state machine.
    """

    def __init__(self, requested_model: str):
        self.requested_model = requested_model
        self.message_id = f"msg_{uuid.uuid4().hex}"
        self.thinking_started = False
        self.text_started = False
        self.active_indices = {}
        self.finish_reason = "end_turn"

    async def generate(self, openai_stream: AsyncGenerator[str, None]) -> AsyncGenerator[str, None]:
        # 1. Message Start
        yield self._event("message_start", {
            "message": {
                "id": self.message_id,
                "type": "message",
                "role": "assistant",
                "content": [],
                "model": self.requested_model
            }
        })

        async for chunk in openai_stream:
            if not chunk.startswith("data: "):
                continue

            data_str = chunk[6:].strip()
            if data_str == "[DONE]":
                break

            try:
                data = json.loads(data_str)
                if not data.get("choices"):
                    continue

                delta = data["choices"][0].get("delta", {})

                # A. Handle Reasoning (Thinking) Block
                reasoning = delta.get("reasoning_content", "") or delta.get("reasoning", "")
                if reasoning:
                    if not self.thinking_started:
                        # Anthropic expects thinking block at early index
                        yield self._event("content_block_start", {
                            "index": 0,
                            "content_block": {"type": "thinking", "thinking": "", "signature": "GhostLLM-k2.5"}
                        })
                        self.active_indices[0] = "thinking"
                        self.thinking_started = True

                    yield self._event("content_block_delta", {
                        "index": 0,
                        "delta": {"type": "thinking_delta", "thinking": reasoning}
                    })

                # B. Handle Text Content Block
                content = delta.get("content", "")
                if content:
                    # If we have text, we should close thinking if it was open? 
                    # Actually Anthropic allows multiple blocks. We'll use index 1 for text.
                    text_idx = 0 if not self.thinking_started else 1


            if not self.text_started:
                if self.thinking_started:
                    # Close the thinking block if we start text? 
                    # Anthropic usually stops the block before starting next.
                    yield self._event("content_block_stop", {"index": 0})

                yield self._event("content_block_start", {
                    "index": text_idx,
                    "content_block": {"type": "text", "text": ""}
                })
                self.active_indices[text_idx] = "text"
                self.text_started = True

            yield self._event("content_block_delta", {
                "index": text_idx,
                "delta": {"type": "text_delta", "text": content}
            })

        # B. Handle Tool Calls
        tool_calls = delta.get("tool_calls")
        if tool_calls:
            for tc in tool_calls:
                tc_index = tc.get("index", 0) + 1 # Offset by 1 for text block
                fn = tc.get("function", {})

                if tc_index not in self.active_indices:
                    self.active_indices[tc_index] = "tool_use"
                    call_id = tc.get("id") or f"call_{uuid.uuid4().hex}"
                    yield self._event("content_block_start", {
                        "index": tc_index,
                        "content_block": {
                            "type": "tool_use",
                            "id": call_id,
                            "name": fn.get("name", "unknown"),
                            "input": {}
                        }
                    })

                    if fn.get("arguments"):
                        yield self._event("content_block_delta", {
                            "index": tc_index,
                            "delta": {"type": "input_json_delta", "partial_json": fn["arguments"]}
                        })
                elif "arguments" in fn:
                    yield self._event("content_block_delta", {
                        "index": tc_index,
                        "delta": {"type": "input_json_delta", "partial_json": fn["arguments"]}
                    })

        # C. Capture Finish Reason
        freason = data["choices"][0].get("finish_reason")
        if freason:
            if freason == "tool_calls":
                self.finish_reason = "tool_use"
            elif freason == "length":
                self.finish_reason = "max_tokens"
            else:
                self.finish_reason = "end_turn"

    except Exception as e:
        logger.error(f"Stream Normalization Error: {e}")
        continue

# 2. Final Sequence
for idx in sorted(self.active_indices.keys(), reverse=True):
    yield self._event("content_block_stop", {"index": idx})

yield self._event("message_delta", {
    "delta": {"stop_reason": self.finish_reason, "stop_sequence": None}
})
yield self._event("message_stop", {})

class ToolUseMapper:
    """
    Bi-directional mapper for Anthropic tool_use and OpenAI tool_calls.
    Ensures that call IDs and data structures are consistent across protocols.
    """

    @staticmethod
    def anthropic_tools_to_openai(anthropic_tools: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Converts Anthropic tool definitions to OpenAI function definitions with strict sanitization."""
        openai_tools = []
        if not anthropic_tools:
            return []

        logger.debug(f"Mapping {len(anthropic_tools)} tools.")

        for tool in anthropic_tools:
            if not isinstance(tool, dict):
                continue

            # Extract common elements with safe fallbacks
            func_data = tool.get("function")
            if not isinstance(func_data, dict):
                # If it's Anthropic format, the tool IS the function data
                func_data = tool

            # 1. Detect and sanitize name
            # Priority: tool['name'] (Anthropic) then func_data['name'] (OpenAI)
            name = tool.get("name") or func_data.get("name")

            if not isinstance(name, str) or not name.strip() or name.lower() == "none":
                logger.warning(f"Discarding tool with invalid name: '{name}'")
                continue

            name = name.strip()

            # 2. Extract description and parameters with strict typing
            description = tool.get("description") or func_data.get("description") or ""
            parameters = tool.get("input_schema") or func_data.get("parameters")

            if not isinstance(parameters, dict):
                parameters = {"type": "object", "properties": {}}

            # 3. Normalized Passthrough/Construction
            mapped = {
                "type": "function",
                "function": {
                    "name": name,
                    "description": str(description),
                    "parameters": parameters
                }

def openai_call_to_anthropic_use(openai_call: Dict[str, Any]) -> Dict[str, Any]:
    """Converts a single OpenAI tool_call to Anthropic tool_use content block with hardening."""
    if not isinstance(openai_call, dict):
        raise ValueError("openai_call must be a dictionary")

    call_id = openai_call.get("id")
    func = openai_call.get("function")
    if not isinstance(func, dict):
        func = {}

    name = func.get("name")

    # Hard validation of identity
    if not isinstance(call_id, str) or not call_id.strip():
        raise ValueError("tool_call missing valid 'id'")
    if not isinstance(name, str) or not name.strip():
        raise ValueError("tool_call missing valid function 'name'")

    args_raw = func.get("arguments", "{}")
    args = {}

    # Safe Argument Parsing
    if isinstance(args_raw, dict):
        args = args_raw
    elif isinstance(args_raw, str):
        try:
            args = json.loads(args_raw)
            if not isinstance(args, dict):
                # If it's valid JSON but not a dict (e.g. "[1,2,3]"), wrap it
                args = {"_wrapped_val": args}
        except (json.JSONDecodeError, TypeError):
            logger.warning(f"Failed to parse tool arguments as JSON: {args_raw}")
            args = {"_raw_arguments": str(args_raw)}
    else:
        args = {"_raw_val": str(args_raw)}

def anthropic_result_to_openai_tool_msg(tool_result: Dict[str, Any]) -> Dict[str, Any]:
    """Converts Anthropic tool_result to OpenAI tool role message with deep serialization."""
    if not isinstance(tool_result, dict):
         return {"role": "tool", "content": "Error: Internal tool result mapping failed (not a dict)"}

    call_id = tool_result.get("tool_use_id")
    if not isinstance(call_id, str) or not call_id.strip():
        # OpenAI requires a valid tool_call_id
        logger.error(f"Missing tool_use_id in tool_result: {tool_result}")
        call_id = "unknown_id"

    content = tool_result.get("content", "")

    # Normalize list content (Anthropic style)
    if isinstance(content, list):
        parts = []
        for block in content:
            if not isinstance(block, dict):
                parts.append(str(block))
                continue

            b_type = block.get("type")
            if b_type == "text":
                parts.append(block.get("text", ""))
            else:
                # Serialize complex blocks (json, images, etc) to string for OpenAI
                parts.append(json.dumps(block, ensure_ascii=False))
        content = "\n".join(parts)
    elif not isinstance(content, str):
        # If content is a dict or other type directly
        content = json.dumps(content, ensure_ascii=False)

    return {
        "role": "tool",
        "tool_call_id": call_id,
        "content": str(content)

