                         >
                            {isStreaming ? <RefreshCw className="w-5 h-5 animate-spin" /> : <Send className="w-5 h-5" />}
                         </button>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          )}

          {/* Other tabs as placeholders for now */}
          {activeTab !== 'chat' && (
