    into the canonical ``upstream_id`` for the provider.

    Examples: ``kimi`` → ``moonshotai/kimi-k2.5``; ``kimi-k2.5`` → ``moonshotai/kimi-k2.5`` when unique.
    If two enabled models share the same basename, the hint is returned unchanged (ambiguous).
    """
    r = (requested or "").strip()
    if not r or not name_to_upstream:
        return r
    values = list(name_to_upstream.values())
    if r in name_to_upstream:
        return name_to_upstream[r]
    if r in values:
        return r
    if "/" not in r:
        basenames = [u for u in values if u.split("/")[-1] == r]
        if len(basenames) == 1:
            return basenames[0]
    return r


